import { fraction } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, PracticeItem } from '../../features/unit-v2/types.ts'
import { same, say } from '../batx1-zientziak-funtzioak/text.ts'

/* ==========================================================================
   Deribatuaren aplikazioak · Batxilergoa 1 · Zientziak — diagnostic,
   guided practice, exercise bank and challenges, with the scope of unit
   11 of Santillana 1.º Bachillerato Ciencias and sections 5–6 of unit 12
   of Anaya Matemáticas I (all the exercises and numbers are our own).
   Every closed answer is a single number: the x where something starts
   or happens, the value of an extremum, a parameter, a count of extrema
   or inflections, or an optimal value. Some optimisation items ask for
   the value and not the x, so that answering x is marked wrong.
   Intervals and whole sketches go in the open items of the bank.
   ========================================================================== */

const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)

/** «Find the x of the …» */
const xOf = (what: { eu: string; es: string; ar: string; en: string }, formula: string) => say(
    `Aurkitu $f(x)=${formula}$ funtzioaren ${what.eu} $x$ abszisa.`,
    `Halla la $x$ ${what.es} de $f(x)=${formula}$.`,
    `أوجد الإحداثي $x$ ${what.ar} في الدالة $f(x)=${formula}$.`,
    `Find the $x$ of the ${what.en} of $f(x)=${formula}$.`
)
const MAXIMUM = { eu: 'maximoaren', es: 'del máximo', ar: 'للقيمة العظمى', en: 'maximum' }
const MINIMUM = { eu: 'minimoaren', es: 'del mínimo', ar: 'للقيمة الصغرى', en: 'minimum' }
const INFLECTION = { eu: 'inflexio-puntuaren', es: 'del punto de inflexión', ar: 'لنقطة الانعطاف', en: 'point of inflection' }
const intervals = (formula: string) => say(`Aurkitu $f(x)=${formula}$ funtzioaren hazkunde-tarteak.`, `Halla los intervalos de crecimiento de $f(x)=${formula}$.`, `أوجد فترات تزايد $f(x)=${formula}$ وتناقصها.`, `Find where $f(x)=${formula}$ increases and decreases.`)
const curvature = (formula: string) => say(`Aztertu $f(x)=${formula}$ funtzioaren kurbadura.`, `Estudia la curvatura de $f(x)=${formula}$.`, `ادرس تقعّر $f(x)=${formula}$.`, `Study the concavity of $f(x)=${formula}$.`)

